<?php declare(strict_types=1);namespace NpmGateway\Services;use NpmGateway\Exceptions\Domain\InvalidSupplyOrderException;
final readonly class SupplyOrderValidator{public function __construct(private RmAuditRichTextSanitizer$sanitizer){}public function validate(array$input):array{try{$rich=$this->sanitizer->sanitize((string)($input['request_html']??''));}catch(\InvalidArgumentException$e){throw new InvalidSupplyOrderException(['request_html'=>str_replace('Audit Findings','Supplies Requested',$e->getMessage())],$input);}return['request_html'=>$rich['html'],'request_text'=>$rich['text']];}}
